import fs from 'node:fs';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {guarded} from './run-small-native-task-guarded-20261025.mjs';import {hash,json} from './seal-simple-website-successor.mjs';
const receipt='F:/VisibleMedicine/staging/20261025-contained-model-preflight-native/SOURCE_CANDIDATE.json';assert.equal(hash(receipt),'967f97c1dd506591502556640124159d19f39fc6c7092cbf96aa7c54e38b381d');const source=json(receipt),site=source.atlas,dir='F:/VisibleMedicine/staging/20261025-teaching-priority-reassessment';const git=(...args)=>execFileSync('git',['-C',site,...args],{encoding:'utf8',windowsHide:true}).trim();assert.equal(git('rev-parse','HEAD'),source.head);assert.equal(git('status','--porcelain'),'');global.gc();const run=await guarded({site,dir,command:'--max-old-space-size=384 scripts/report-teaching-gaps.mjs --readiness=pending',heap:384,aggregate:1024,minimum:3072});assert(run.passing);assert.equal(git('rev-parse','HEAD'),source.head);assert.equal(git('status','--porcelain'),'');const raw=dir+'/runner.stdout.log',report=json(raw);assert.equal(report.evidence.sourceRevision,source.head);assert.equal(report.evidence.workingTreeDirty,false);assert.equal(report.rows.length,report.matchingRows);const counts={};for(const r of report.rows){const key=r.region+':'+r.topic;counts[key]=(counts[key]??0)+1;}const result={at:new Date().toISOString(),passing:true,source:{path:receipt,sha256:hash(receipt)},run,report:{path:raw,sha256:hash(raw)},structureCount:report.structureCount,placementCount:report.placementCount,totals:report.totals,pending:report.rows.length,counts,ct:report.rows.filter(r=>r.topic==='ct'),mri:report.rows.filter(r=>r.topic==='mri'),clinicalApproval:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({result:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),pending:result.pending,counts,ct:result.ct.map(r=>({name:r.name,id:r.id,region:r.region,system:r.system})),mri:result.mri.map(r=>({name:r.name,id:r.id,region:r.region,system:r.system}))}));
